/**
 * THE BUILD STAMP, declared for TypeScript. Replaced at build time by vite's `define` (see
 * `vite/config.prod.mjs`), so these are compile-time constants, not runtime lookups.
 *
 * Declared in their own file rather than appended to an existing one so that deleting the
 * stamp means deleting a file — a change nobody makes by accident.
 */
declare const __BUILD_SHA__: string;
declare const __BUILT_AT__: string;
